+// `AbortSignal.abort().reason` is a `DOMException`, which is not a native error,
+// so it carries no stack and is rejected by common error assertion and
+// serialization tooling. Same name and message, but an actual `Error`.
+function createAbortError() {
+	const error = new Error('This operation was aborted');
+	error.name = 'AbortError';
+	return error;
+}
